def ptext(key: str, *, locale: str | None = None, **params: object) -> str:
    selected = locale or current_locale()
    index = {"zh_CN": 0, "en_US": 1, "ja_JP": 2}.get(selected, 0)
    template = _COPY.get(key, (key, key, key))[index]
    return template.format(**params)
